import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template<typename T>
__global__ void fused_ops_kernel(const T* conv_out, const T* bias, T* out, int B, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_spatial = B * D * H * W;
    if (idx >= total_spatial) return;

    int b = idx / (D * H * W);
    int remaining = idx % (D * H * W);
    int d = remaining / (H * W);
    remaining = remaining % (H * W);
    int h = remaining / W;
    int w = remaining % W;

    int spatial_offset = d * H * W + h * W + w;
    int base = b * C * D * H * W + spatial_offset;

    T max_val = -INFINITY;
    for (int c = 0; c < C; ++c) {
        int input_idx = base + c * D * H * W;
        T val = conv_out[input_idx];
        max_val = fmaxf(max_val, val);
    }

    T sum_exp = 0;
    for (int c = 0; c < C; ++c) {
        int input_idx = base + c * D * H * W;
        sum_exp += expf(conv_out[input_idx] - max_val);
    }

    T logsumexp = max_val + logf(sum_exp);

    // Apply activation: x * sigmoid(x + 3) /6
    T x = logsumexp;
    T sig = 1.0f / (1.0f + expf(-(x + 3.0f)));
    T activated = x * sig / 6.0f;

    // Subtract bias and clamp
    T result = fmaxf(fminf(activated - bias[0], 1.0f), -1.0f);

    int output_idx = b * D * H * W + spatial_offset;
    out[output_idx] = result;
}

torch::Tensor fused_ops_cuda(torch::Tensor conv_out, torch::Tensor bias) {
    auto B = conv_out.size(0);
    auto C = conv_out.size(1);
    auto D = conv_out.size(2);
    auto H = conv_out.size(3);
    auto W = conv_out.size(4);
    auto out = torch::zeros({B, 1, D, H, W}, conv_out.options());

    int total_spatial = B * D * H * W;
    int block_size = 256;
    int grid_size = (total_spatial + block_size - 1) / block_size;

    fused_ops_kernel<<<grid_size, block_size>>>(
        conv_out.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W
    );

    return out;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_ops_cuda(torch::Tensor conv_out, torch::Tensor bias);"

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super().__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride, padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        summed_bias = self.bias.sum().view(1)
        x = self.fused_ops.fused_ops_cuda(x, summed_bias)
        return x
